546	        $explicit = $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
547	        if (is_string($explicit) && trim($explicit) !== '') {
548	            return $configured;
