552	            $default = (string) config('filesystems.default', 'local');
553	            $defaultConfig = config("filesystems.disks.{$default}");
554	
555	            if (
556	                $default !== '' &&
557	                $default !== 'local' &&
558	                $default !== 'media' &&
559	                is_array($defaultConfig) &&
560	                (($defaultConfig['driver'] ?? null) === 's3')
561	            ) {
562	                return $default;
563	            }
564	        }
565	
566	        return $configured;
